console.log(score ?? 10);
const age = 18;
console.log(age >= 18 ? "adult" : "minor");

let total = 0;
for (let i = 1; i <= 5; i++) total += i;
console.log(total);

function add(a, b = 1) { return a + b; }
console.log(add(4, 3));
console.log(add(4));

function makeCounter() {
  let count = 0;
  return () => ++count;
}
const next = makeCounter();
console.log(next());
console.log(next());

const user = {name: "Mira", points: 10};
const updated = {...user, points: 15};
console.log(user.points);
console.log(updated.points);

const unique = new Set(["html", "css", "html"]);
console.log([...unique].join(","));
const names = new Map([["js", "JavaScript"]]);
console.log(names.get("js"));

class Counter {
  #count = 0;
  increment() { this.#count++; }
  value() { return this.#count; }
}
const counter = new Counter();
counter.increment(); counter.increment();
console.log(counter.value());

function divide(a, b) {
  if (b === 0) throw new Error("Division by zero");
  return a / b;
}
try { divide(4, 0); } catch (error) { console.log(error.message); }

import {strictEqual} from "node:assert";
strictEqual(2 + 3, 5);
console.log("Module check passed");

console.log("A");
Promise.resolve().then(() => console.log("B"));
console.log("C");

const response = Response.json({name: "Mira"});
if (!response.ok) throw new Error(`HTTP ${response.status}`);
const data = await response.json();
console.log(data.name);

const controller = new AbortController();
controller.signal.addEventListener("abort", () => console.log("cancelled"), {once:true});
controller.abort();
console.log(controller.signal.aborted);

const heading = document.querySelector("#app h1");
heading.textContent = "Hello DOM";
console.log(heading.textContent);

let count = 0;
const button = document.querySelector("#add");
button.addEventListener("click", () => count++);
button.dispatchEvent(new window.Event("click", {bubbles:true}));
button.dispatchEvent(new window.Event("click", {bubbles:true}));
console.log(count);

const rawInput = "  Mira  ";
const name = rawInput.trim();
if (!name) throw new Error("Name required");
const state = {name};
console.log(`Welcome, ${state.name}`);

const saved = JSON.stringify({theme:"dark", version:1});
const restored = JSON.parse(saved);
console.log(restored.theme);
console.log(restored.version);

import assert from "node:assert/strict";
const clamp = (value, min, max) => Math.min(max, Math.max(min, value));
assert.equal(clamp(12,0,10),10);
assert.equal(clamp(-2,0,10),0);
console.log("Tests passed");

const pattern = /^[A-Z]{3}\d{2}$/;
console.log(pattern.test("ABC12"));
console.log(pattern.test("abc12"));

const date = new Date("2026-01-02T00:00:00Z");
console.log(date.toISOString());
console.log(date.getUTCFullYear());

function* count() {
  yield 1; yield 2; yield 3;
}
console.log([...count()].join(","));

const config = Object.freeze({enabled:true});
console.log(Object.isFrozen(config));
console.log(Object.getOwnPropertyDescriptor(config,"enabled").writable);

const right = new Set([3,4,5]);
const result = [...new Set([1,2,3,4])].filter(x => right.has(x));
console.log(result.join(","));

const node = document.createElement("p");
node.textContent = "<img src=x>";
console.log(node.innerHTML);

import {writeFile, readFile} from "node:fs/promises";
await writeFile("/tmp/example.txt","hello","utf8");
console.log(await readFile("/tmp/example.txt","utf8"));

import assert from "node:assert/strict";
