public class Main {
  public static void main(String[] args) throws Exception {
    // Create Item(name,quantity), reject negative quantities, sum quantities 3 and 4, assert 7, and print Total: 7.
  }
}

lessons.solution_html:
public class Main {
  record Item(String name,int quantity) {
    Item { if (name == null || name.isBlank() || quantity < 0) throw new IllegalArgumentException(); }
  }
  public static void main(String[] args) {
    var items = java.util.List.of(new Item("Pen",3),new Item("Book",4));
    int total = items.stream().mapToInt(Item::quantity).sum();
    if (total != 7) throw new AssertionError();
    System.out.println("Total: " + total);
  }
}

